-- Weekly Arena 2027-W01: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2027-W01', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2027-01-04T00:00:00.000Z', '2027-01-11T00:00:00.000Z', 60, 'published', $WKd82457ef478a$[{"id":"wk-2027-w01-01-fb4b","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $28$ and $10$ and each non-parallel side has length $15$. Find its area.","type":"text","correctAnswer":"228","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $9$ and hypotenuse $15$.","solution":"The height is $\\sqrt{15^2-9^2}=12$, so the area is $\\tfrac12(28+10)(12)=228$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w01-02-0044","title":"Sum of Divisors","topic":"Number Theory","level":"Foundation","question":"Find the sum of all positive divisors of $504$.","type":"text","correctAnswer":"1560","hint":"Factor $N$ into primes; the divisor sum is multiplicative.","solution":"$504=7^{1}\\cdot 2^{3}\\cdot 3^{2}$, so the divisor sum is $1560$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2027-w01-03-ad9d","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $942$ that are divisible by $4$ or by $5$ (or both).","type":"text","correctAnswer":"177190","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $4$, $5$ and $20$ gives $177190$.","answerMode":"numeric-grid","answerDigits":6,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2027-w01-04-f962","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $31$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=1$. Find $PA + PB + PT$.","type":"text","correctAnswer":"993","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=31^2/1=961$, so the sum is $1+961+31=993$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2027-w01-05-e374","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(5,6)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(4,5)$?","type":"text","correctAnswer":"210","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{11}{5}-\\binom{9}{4}\\binom{2}{1}=210$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w01-06-ffae","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 9 \\pmod{11}$, $n\\equiv 1 \\pmod{5}$, $n\\equiv 5 \\pmod{7}$.","type":"text","correctAnswer":"306","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $306$ modulo $385$, and $306$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w01-07-9c23","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 8t + 1 = 0$. Find the remainder when $r^{8} + s^{8}$ is divided by $1000$.","type":"text","correctAnswer":"962","hint":"Let $S_k=r^k+s^k$. Then $S_k=8S_{k-1}-1S_{k-2}$, with $S_0=2$, $S_1=8$.","solution":"Using $S_k=8S_{k-1}-1S_{k-2}$ from $S_0=2$, $S_1=8$ gives $S_{8}=14760962$, whose remainder modulo $1000$ is $962$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w01-08-eaee","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 5-tuples $(x_1,\\dots,x_5)$ of non-negative integers satisfy $x_1+\\cdots+x_5=19$ with every $x_i\\le 7$?","type":"text","correctAnswer":"2380","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $2380$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2027-w01-09-56e8","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{55} \\left\\lfloor \\frac{9k}{10} \\right\\rfloor$.","type":"text","correctAnswer":"1360","hint":"Write $9k=10q+r$ and track how the remainder cycles with period $10$.","solution":"Evaluating each floor term and adding gives $1360$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2027-w01-10-9ce9","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(7,11)$ and $(1,6)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"15","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $31$ and the boundary has $B=3$ lattice points, so $I=(31-3+2)/2=15$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WKd82457ef478a$::jsonb
where not exists (select 1 from public.arenas where title = 'Weekly Arena 2027-W01');
